<template x-if="modal==='maps'"><div class="form-stack">
    <div class="module-toolbar"><label>OLT<select x-model="mapOlt" @change="renderFtth()"><option value="all">Semua OLT</option><template x-for="olt in db.olts" :key="olt.id"><option :value="String(olt.id)" x-text="olt.name"></option></template></select></label><button class="btn secondary" @click="loadFtth()">Muat ulang peta</button><button class="btn primary" x-show="db.permissions.operate" @click="editNode()">Tambah perangkat FTTH</button></div>
    <div id="ftth-map" class="ftth-map" aria-label="Peta jaringan FTTH"></div>
    <p class="small muted">Klik perangkat untuk detail. Saat form terbuka, klik peta untuk mengisi koordinat. Garis menghubungkan perangkat dengan induknya.</p>
    <template x-if="nodeForm"><form class="form-stack inline-editor" @submit.prevent="saveNode()"><h3 x-text="nodeForm.id?'Edit perangkat FTTH':'Tambah perangkat FTTH'"></h3><div class="form-grid">
        <label>Nama perangkat<input x-model="nodeForm.name" required maxlength="120" :disabled="!db.permissions.operate"></label><label>Tipe perangkat<select x-model="nodeForm.type" :disabled="!db.permissions.operate"><option>OTB</option><option>ODC</option><option>ODP</option><option>POLE</option></select></label>
        <label>OLT perangkat<select aria-label="OLT perangkat" x-model.number="nodeForm.olt_id" :disabled="!db.permissions.operate"><template x-for="olt in db.olts" :key="olt.id"><option :value="olt.id" x-text="olt.name"></option></template></select></label><label>Perangkat induk<select aria-label="Perangkat induk" x-model="nodeForm.parent_id" :disabled="!db.permissions.operate"><option value="">Langsung dari OLT / belum dipetakan</option><template x-for="node in ftth.nodes.filter(n=>n.olt_id===Number(nodeForm.olt_id)&&n.id!==nodeForm.id)" :key="node.id"><option :value="node.id" x-text="node.type+' '+node.name"></option></template></select></label>
        <label>Latitude<input type="number" step="any" x-model.number="nodeForm.latitude" min="-90" max="90" required :disabled="!db.permissions.operate"></label><label>Longitude<input type="number" step="any" x-model.number="nodeForm.longitude" min="-180" max="180" required :disabled="!db.permissions.operate"></label><label>Kapasitas port<input type="number" x-model.number="nodeForm.capacity" min="1" max="1024" required :disabled="!db.permissions.operate"></label><label>Deskripsi perangkat<input x-model="nodeForm.description" maxlength="2000" :disabled="!db.permissions.operate"></label>
    </div><div class="modal-actions"><button type="button" class="btn secondary" @click="nodeForm=null">Tutup detail</button><button type="button" class="btn danger-solid" x-show="db.permissions.operate&&nodeForm.id" @click="deleteNode(nodeForm)" :disabled="busy">Hapus perangkat</button><button class="btn primary" x-show="db.permissions.operate" :disabled="busy">Simpan perangkat FTTH</button></div></form></template>
    <div class="table-scroll"><table><thead><tr><th>Perangkat</th><th>OLT</th><th>Port terpakai</th><th>Aksi</th></tr></thead><tbody><template x-for="node in filteredFtthNodes()" :key="node.id"><tr><td x-text="node.type+' '+node.name"></td><td x-text="oltName(node.olt_id)"></td><td x-text="node.assignments_count+' / '+node.capacity"></td><td><button class="text-button" @click="editNode(node)">Detail perangkat</button></td></tr></template></tbody></table></div>
    <p class="muted" x-show="!ftth.nodes.length">Belum ada perangkat FTTH. Tambahkan OTB, ODC, atau ODP untuk mulai memetakan jaringan.</p>
    <form class="form-grid inline-editor" @submit.prevent="assignOnu()" x-show="db.permissions.operate"><label>ODP tujuan<select aria-label="ODP tujuan" x-model="assignmentForm.node_id" required><option value="">Pilih ODP</option><template x-for="node in ftth.nodes.filter(n=>n.type==='ODP')" :key="node.id"><option :value="node.id" x-text="node.name+' ('+oltName(node.olt_id)+')'"></option></template></select></label><label>ONU pelanggan<select aria-label="ONU pelanggan" x-model="assignmentForm.onu_id" required><option value="">Pilih ONU</option><template x-for="onu in db.onus.filter(o=>o.olt_id===ftth.nodes.find(n=>n.id===Number(assignmentForm.node_id))?.olt_id)" :key="onu.id"><option :value="onu.id" x-text="onu.name+' / '+onu.sn+' / '+onu.interface"></option></template></select></label><label>Port ODP<input type="number" x-model.number="assignmentForm.port_number" min="1" max="1024" required></label><button class="btn primary" :disabled="busy">Hubungkan ONU</button></form>
    <div class="table-scroll"><table><thead><tr><th>ODP</th><th>Port</th><th>ONU</th><th>Aksi</th></tr></thead><tbody><template x-for="assignment in ftth.assignments" :key="assignment.id"><tr><td x-text="ftth.nodes.find(n=>n.id===assignment.node_id)?.name"></td><td x-text="assignment.port_number"></td><td x-text="db.onus.find(o=>o.id===assignment.onu_id)?.name||'ONU tidak aktif'"></td><td><button class="text-button red-text" x-show="db.permissions.operate" @click="detachOnu(assignment.onu_id)">Lepaskan</button></td></tr></template></tbody></table></div>
</div></template>
